from fractions import Fraction

def gaussian_elimination(A):
    rows = len(A)
    cols = len(A[0])
    for i in range(rows):
        # Find pivot
        max_row = i
        for r in range(i+1, rows):
            if abs(A[r][i]) > abs(A[max_row][i]):
                max_row = r
        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate below
        factor = Fraction(1, A[i][i])
        for j in range(i+1, cols):
            A[i][j] *= factor
        A[i][i] = 1

        # Eliminate above
        for r in range(rows):
            if r != i:
                factor = Fraction(A[r][i], A[i][i])
                for j in range(i, cols):
                    A[r][j] -= factor * A[i][j]
                A[r][i] = 0

    # Back substitution
    for i in range(rows-1, -1, -1):
        for j in range(i+1, rows):
            A[i][cols-1] -= A[j][cols-1] * A[i][j]
        A[i][cols-1] /= A[i][i]

    return [row[cols-1] for row in A]

def compute_rho(G):
    n = len(G)
    A = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if G[i][j]:
                A[i][j] = Fraction(1, math.sqrt(2))
                A[j][i] = Fraction(1, math.sqrt(2))

    rank = len(gaussian_elimination(A))
    return rank

def brute_force_xor_circuit(n):
